#include "stdlib/lapack/base/dsyconvf_rook.h"
#include "stdlib/lapack/base/shared.h"
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>

#define ITERATIONS 1000
#define REPEATS 2

/**
* Returns a clock time in seconds.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Runs conversion/reversion cycles and validates the final factor storage.
*
* @param N        matrix order
* @param uplo     stored triangle
* @param ndarray  whether to use the ndarray interface
* @return         elapsed seconds or -1 on failure
*/
static double benchmark( const LAPACK_INT N, const LAPACK_UPLO uplo, const int ndarray ) {
	double *A;
	double *E;
	LAPACK_INT *IPIV;
	LAPACK_INT info;
	LAPACK_INT i;
	LAPACK_INT j;
	double elapsed;
	double t;
	int k;

	A = (double *)malloc( (size_t)(N*N) * sizeof( double ) );
	E = (double *)malloc( (size_t)N * sizeof( double ) );
	IPIV = (LAPACK_INT *)malloc( (size_t)N * sizeof( LAPACK_INT ) );
	if ( A == NULL || E == NULL || IPIV == NULL ) {
		fprintf( stderr, "Error allocating benchmark buffers.\n" );
		free( A );
		free( E );
		free( IPIV );
		return -1.0;
	}
	for ( i = 0; i < N; i++ ) {
		IPIV[ i ] = i + 1;
		E[ i ] = -9.0;
		for ( j = 0; j < N; j++ ) {
			A[ (i*N)+j ] = (double)(i+j) + 1.0;
		}
	}
	IPIV[ 0 ] = -1;
	IPIV[ 1 ] = -2;
	info = 0;

	t = tic();
	for ( k = 0; k < ITERATIONS; k++ ) {
		if ( ndarray ) {
			info = API_SUFFIX(c_dsyconvf_rook_ndarray)( uplo, 'C', N, A, N, 1, 0, E, 1, 0, IPIV, 1, 0 );
		} else {
			info = API_SUFFIX(c_dsyconvf_rook)( LAPACK_ROW_MAJOR, uplo, 'C', N, A, N, E, IPIV );
		}
		if ( info != 0 ) {
			break;
		}
		if ( ndarray ) {
			info = API_SUFFIX(c_dsyconvf_rook_ndarray)( uplo, 'R', N, A, N, 1, 0, E, 1, 0, IPIV, 1, 0 );
		} else {
			info = API_SUFFIX(c_dsyconvf_rook)( LAPACK_ROW_MAJOR, uplo, 'R', N, A, N, E, IPIV );
		}
		if ( info != 0 ) {
			break;
		}
	}
	elapsed = tic() - t;
	if ( info != 0 || IPIV[ 0 ] != -1 || IPIV[ 1 ] != -2 ) {
		elapsed = -1.0;
	}
	for ( i = 0; i < N; i++ ) {
		for ( j = 0; j < N; j++ ) {
			if ( A[ (i*N)+j ] != (double)(i+j) + 1.0 ) {
				elapsed = -1.0;
			}
		}
	}
	if ( ( uplo == LAPACK_UPPER_TRIANGLE && E[ 1 ] != 2.0 ) || ( uplo == LAPACK_LOWER_TRIANGLE && E[ 0 ] != 2.0 ) ) {
		elapsed = -1.0;
	}
	free( A );
	free( E );
	free( IPIV );
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	const LAPACK_INT sizes[] = { 8, 32 };
	const LAPACK_UPLO uplos[] = { LAPACK_UPPER_TRIANGLE, LAPACK_LOWER_TRIANGLE };
	double elapsed;
	int count;
	int passing;
	int i;
	int j;
	int k;
	int r;

	count = 0;
	passing = 0;
	printf( "TAP version 13\n" );
	for ( i = 0; i < 2; i++ ) {
		for ( j = 0; j < 2; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				for ( r = 0; r < REPEATS; r++ ) {
					count += 1;
					printf( "# c::dsyconvf-rook:N=%d:uplo=%s:ndarray=%d\n", (int)sizes[ i ], j ? "lower" : "upper", k );
					elapsed = benchmark( sizes[ i ], uplos[ j ], k );
					if ( elapsed < 0.0 ) {
						printf( "not ok %d benchmark failed\n", count );
					} else {
						printf( "  ---\n" );
						printf( "  iterations: %d\n", ITERATIONS );
						printf( "  elapsed: %0.9f\n", elapsed );
						printf( "  ...\n" );
						printf( "ok %d benchmark finished\n", count );
						passing += 1;
					}
				}
			}
		}
	}
	printf( "1..%d\n", count );
	printf( "# total %d\n", count );
	printf( "# pass  %d\n", passing );
	if ( passing == count ) {
		printf( "# ok\n" );
		return EXIT_SUCCESS;
	}
	return EXIT_FAILURE;
}
